    min_val = float('inf')
    best_quad = None
    for d in range(1, 1000):
        for c in range(1, 1000):
            k2 = c*c - 6*c*d + d*d
            if k2 >= 0:
                k = int(k2**0.5)
                if k*k == k2:
                    # We have a potential solution. Now check if a,b are integers.
                    # a+b = c+d, ab = 2cd
                    # t^2 - (c+d)t + 2cd = 0
                    # discriminant D = (c+d)^2 - 8cd = c^2 - 6cd + d^2 = k^2
                    # a, b = (c+d \pm k) / 2
                    if (c+d+k) % 2 == 0 and (c+d-k) % 2 == 0:
                        a = (c+d+k) // 2
                        b = (c+d-k) // 2
                        if a > 0 and b > 0:
                            val = (c*c + d*d) / (c*d)
                            if val < min_val:
                                min_val = val
                                best_quad = (a, b, c, d)
    return min_val, best_quad

